export type RailwayStatusCategory =
  | 'AVAILABLE'
  | 'WAITLISTED'
  | 'RAC'
  | 'UNAVAILABLE'
  | 'UNKNOWN';

export interface RailwayAvailabilityBreakdown {
  rawStatus: string;
  category: RailwayStatusCategory;
  isConfirmed: boolean;
  isWaitlisted: boolean;
  isRac: boolean;
  isUnavailable: boolean;
  seatCount: number | null;
  waitlistType: string | null;
  waitlistNumber: number | null;
  racNumber: number | null;
  statusBadge: string;
  headline: string;
  seatSummary: string;
  explanation: string;
  badgeClass: string;
  containerClass: string;
  iconSymbol: string;
}

export function parseRailwayAvailability(
  rawInput: unknown
): RailwayAvailabilityBreakdown {
  let raw = '';
  if (typeof rawInput === 'string') {
    raw = rawInput.trim();
  } else if (rawInput && typeof rawInput === 'object') {
    const obj = rawInput as Record<string, any>;
    raw = String(obj.status || obj.availabilityText || obj.current_status || '').trim();
  }

  if (!raw) {
    return {
      rawStatus: '',
      category: 'UNKNOWN',
      isConfirmed: false,
      isWaitlisted: false,
      isRac: false,
      isUnavailable: false,
      seatCount: null,
      waitlistType: null,
      waitlistNumber: null,
      racNumber: null,
      statusBadge: 'Not Checked',
      headline: 'Availability Not Checked',
      seatSummary: 'Status not yet verified',
      explanation: 'Tap verify to check real-time availability on IRCTC.',
      badgeClass: 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border-slate-200 dark:border-slate-700',
      containerClass: 'bg-card border-slate-200 dark:border-slate-800',
      iconSymbol: '⚪',
    };
  }

  const s = raw.toUpperCase();

  // 1. REGRET / NOT AVAILABLE / CLASS NOT AVAILABLE / CANCELLED / UNAVAILABLE / NO ROOM / BLOCKED / DEPARTED / CHARTING DONE
  // Must be evaluated BEFORE available checks to avoid "NOT AVAILABLE".includes('AVAILABLE') false positive!
  const isRegret =
    s.includes('REGRET') ||
    s.includes('NOT AVAILABLE') ||
    s.includes('CLASS NOT AVAILABLE') ||
    s.includes('CANCELLED') ||
    s.includes('CANCELED') ||
    s.includes('UNAVAILABLE') ||
    s.includes('NO ROOM') ||
    s.includes('BLOCKED') ||
    s.includes('TRAIN DEPARTED') ||
    s.includes('DEPARTED') ||
    s.includes('CHARTING DONE') ||
    s.includes('CHART PREPARED') ||
    s.includes('BOOKING CLOSED');

  if (isRegret) {
    return {
      rawStatus: raw,
      category: 'UNAVAILABLE',
      isConfirmed: false,
      isWaitlisted: false,
      isRac: false,
      isUnavailable: true,
      seatCount: 0,
      waitlistType: null,
      waitlistNumber: null,
      racNumber: null,
      statusBadge: 'Not Available',
      headline: 'Booking Closed / Unavailable',
      seatSummary: '0 Seats Available (Booking Closed)',
      explanation: 'No tickets or waiting list accepted for this class/route on IRCTC.',
      badgeClass: 'bg-rose-500/15 text-rose-700 dark:text-rose-400 border-rose-500/30',
      containerClass: 'bg-card border-rose-500/30 dark:border-rose-500/40',
      iconSymbol: '🔴',
    };
  }

  // 2. AVAILABLE / AVL / CURR_AVBL / CNF
  const avlMatch = s.match(/(?:AVAILABLE|AVL|CURR_AVBL|CURR\s*AVBL)\s*(\d+)?/i);
  if (avlMatch || s.includes('AVAILABLE') || s.includes('AVL') || s.startsWith('CNF')) {
    let count: number | null = null;
    if (avlMatch && avlMatch[1]) {
      count = parseInt(avlMatch[1], 10);
    } else {
      const numMatch = s.match(/\d+/);
      if (numMatch) count = parseInt(numMatch[0], 10);
    }

    const badgeText = count !== null ? `AVL ${count}` : 'AVAILABLE';
    const headlineText = count !== null ? `Available: ${count} Seats` : 'Available: Confirmed';
    const summaryText = count !== null ? `${count} Seats Available` : 'Confirmed Seats Available';

    return {
      rawStatus: raw,
      category: 'AVAILABLE',
      isConfirmed: true,
      isWaitlisted: false,
      isRac: false,
      isUnavailable: false,
      seatCount: count,
      waitlistType: null,
      waitlistNumber: null,
      racNumber: null,
      statusBadge: badgeText,
      headline: headlineText,
      seatSummary: summaryText,
      explanation: count !== null
        ? `${count} confirmed seat(s) available for immediate reservation on IRCTC.`
        : 'Confirmed seat reservation ready for booking.',
      badgeClass: 'bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 border-emerald-500/30',
      containerClass: 'bg-card border-emerald-500/30 dark:border-emerald-500/40',
      iconSymbol: '✔',
    };
  }

  // 2. RAC (Reservation Against Cancellation)
  if (s.includes('RAC')) {
    const racMatch = s.match(/RAC\s*(\d+)/i) || s.match(/\d+/);
    const racNum = racMatch ? parseInt(racMatch[1] || racMatch[0], 10) : null;
    const badgeText = racNum !== null ? `RAC ${racNum}` : 'RAC';

    return {
      rawStatus: raw,
      category: 'RAC',
      isConfirmed: false, // RAC is NOT confirmed solo seat availability (never confirmed)
      isWaitlisted: false,
      isRac: true,
      isUnavailable: false,
      seatCount: 0,
      waitlistType: 'RAC',
      waitlistNumber: null,
      racNumber: racNum,
      statusBadge: badgeText,
      headline: racNum !== null ? `RAC ${racNum} (Shared Berth)` : 'RAC Confirmed',
      seatSummary: '0 Solo Seats (Shared Sitting Berth Guaranteed)',
      explanation: 'Reservation Against Cancellation: Boarding permitted with guaranteed sitting berth. Upgrades to full berth if cancellations occur.',
      badgeClass: 'bg-amber-500/15 text-amber-700 dark:text-amber-400 border-amber-500/30',
      containerClass: 'bg-card border-amber-500/30 dark:border-amber-500/40',
      iconSymbol: '🟡',
    };
  }

  // 3. WAITLISTED (PQWL, RLWL, GNWL, TQWL, RSWL, WL)
  const isPqwl = s.includes('PQWL');
  const isRlwl = s.includes('RLWL');
  const isGnwl = s.includes('GNWL');
  const isTqwl = s.includes('TQWL');
  const isRswl = s.includes('RSWL');
  const isGenericWl = s.includes('WL');

  if (isPqwl || isRlwl || isGnwl || isTqwl || isRswl || isGenericWl) {
    const wlType = isPqwl ? 'PQWL' : isRlwl ? 'RLWL' : isGnwl ? 'GNWL' : isTqwl ? 'TQWL' : isRswl ? 'RSWL' : 'WL';
    
    // Extract current waitlist position (e.g. PQWL 42 or PQWL 80/WL 42)
    const splitMatch = s.match(new RegExp(`${wlType}\\s*(?:\\d+\\s*\\/\\s*WL\\s*)?(\\d+)`, 'i'));
    const anyNumMatch = s.match(/\d+$/) || s.match(/\d+/);
    const wlNum = splitMatch && splitMatch[1] ? parseInt(splitMatch[1], 10) : anyNumMatch ? parseInt(anyNumMatch[0], 10) : null;

    let typeFullName = 'Waitlist';
    let typeDescription = 'Zero seats currently available. Booking requires ticket cancellations to confirm.';
    if (isPqwl) {
      typeFullName = 'Pooled Quota Waitlist';
      typeDescription = 'Pooled Quota: 0 seats available right now. Requires cancellations from intermediate stations.';
    } else if (isRlwl) {
      typeFullName = 'Remote Location Waitlist';
      typeDescription = 'Remote Location: 0 seats available right now. Remote station quota awaiting cancellations.';
    } else if (isGnwl) {
      typeFullName = 'General Quota Waitlist';
      typeDescription = 'General Quota: 0 seats available right now. Highest priority on direct cancellations.';
    } else if (isTqwl) {
      typeFullName = 'Tatkal Quota Waitlist';
      typeDescription = 'Tatkal Waitlist: 0 seats available right now. Very low probability of clearance.';
    }

    const badgeText = wlNum !== null ? `${wlType} ${wlNum}` : wlType;
    const headlineText = wlNum !== null ? `Waitlisted: ${wlType} ${wlNum}` : `Waitlisted (${wlType})`;

    return {
      rawStatus: raw,
      category: 'WAITLISTED',
      isConfirmed: false,
      isWaitlisted: true,
      isRac: false,
      isUnavailable: false,
      seatCount: 0,
      waitlistType: wlType,
      waitlistNumber: wlNum,
      racNumber: null,
      statusBadge: badgeText,
      headline: headlineText,
      seatSummary: wlNum !== null
        ? `0 Seats Available (Waitlist Position #${wlNum})`
        : '0 Seats Available (Waitlisted)',
      explanation: `${typeFullName}. ${typeDescription}`,
      badgeClass: isTqwl
        ? 'bg-rose-500/15 text-rose-700 dark:text-rose-400 border-rose-500/30'
        : 'bg-amber-500/15 text-amber-700 dark:text-amber-400 border-amber-500/30',
      containerClass: 'bg-card border-amber-500/30 dark:border-amber-500/40',
      iconSymbol: '⚠️',
    };
  }


  // Fallback
  return {
    rawStatus: raw,
    category: 'UNKNOWN',
    isConfirmed: false,
    isWaitlisted: false,
    isRac: false,
    isUnavailable: false,
    seatCount: null,
    waitlistType: null,
    waitlistNumber: null,
    racNumber: null,
    statusBadge: raw.length > 12 ? raw.substring(0, 12) : raw,
    headline: raw,
    seatSummary: raw,
    explanation: 'Status verified from railway reservation system.',
    badgeClass: 'bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border-slate-200 dark:border-slate-700',
    containerClass: 'bg-card border-slate-200 dark:border-slate-800',
    iconSymbol: 'ℹ️',
  };
}

